insert into promo_items (id, r, data)
select 'item-10822', 10822, $j${"cat": "PROMO", "nm": "Kai'Sa - Daughter of the Void (RC Stuttgart Plated Legend)", "ev": "RC - Stuttgart, Germany", "se": "OGN", "ty": "Card", "tg": "Legend\nKai'Sa\nRegional Championship\nPlated Legend", "do": "Fury\nMind", "ra": "Overnumber Showcase", "inf": "Overnumbered foil Plated Legend with the Regional Championship stamp. Only one of each was given out at the Regional Championship Europe in Stuttgart (November 2026): the top 58 players drafted them in finishing order. This one went to pick #4, Ty Weiser-Podlech.", "la": "English", "pt": "By itself", "fo": true, "tn": true, "r": 10822, "id": "item-10822"}$j$::jsonb || jsonb_build_object('st', coalesce((select data->>'st' from promo_items where upper(data->>'st')='NEED' limit 1),'NEED'))
where not exists (select 1 from promo_items where id = 'item-10822' or (data->>'nm' = $n$Kai'Sa - Daughter of the Void (RC Stuttgart Plated Legend)$n$ and data->>'la' = 'English'));
